"""Every rule of the request, checked on a finished plan in plain Python, apart from the model."""

from __future__ import annotations

from .fleet import FIRST_YEAR, KINDS, Transformer
from .report import outages, spend_by_year
from .request import Request


def violations(fleet: list[Transformer], request: Request, replace: dict[str, int]) -> list[str]:
    """One line per broken rule; an empty list means the plan keeps every rule."""
    by_id = {t.tid: t for t in fleet}
    found = []
    for tid, y in sorted(replace.items()):
        if y not in request.plan_years():
            found.append(f"{tid}: {y} is outside the plan")
        if by_id[tid].age < request.min_age:
            found.append(f"{tid}: younger than {request.min_age}, not a candidate")
    for y, spend in spend_by_year(fleet, replace, request.outage_cost).items():
        if spend > request.budget:
            found.append(f"budget {y}: {spend} > {request.budget}")
    if request.outages is not None:
        taken: dict[tuple[str, int], int] = {}
        region = {t.substation: t.region for t in fleet}
        for s, y in outages(fleet, replace):
            taken[region[s], y] = taken.get((region[s], y), 0) + 1
        found += [f"outages {r} {y}: {n} > {request.outages}" for (r, y), n in sorted(taken.items())
                  if n > request.outages]
    if request.crew_weeks is not None:
        weeks: dict[tuple[str, int], int] = {}
        for tid, y in replace.items():
            t = by_id[tid]
            weeks[t.region, y] = weeks.get((t.region, y), 0) + KINDS[t.kind].crew_weeks
        found += [f"crews {r} {y}: {w} > {request.crew_weeks}" for (r, y), w in sorted(weeks.items())
                  if w > request.crew_weeks]
    if request.lead_times:
        for kind, k in KINDS.items():
            early = sum(1 for tid, y in replace.items()
                        if by_id[tid].kind == kind and y < FIRST_YEAR + k.lead_years)
            if early > request.spares.get(kind, 0):
                found.append(f"spares {kind}: {early} > {request.spares.get(kind, 0)}")
    return found

"""The MathOpt model: when to replace each candidate transformer, within each year's budget,
with one outage per substation and year that has replacements, crews per region, and spares for
units needed sooner than a new one can be delivered.

Built for fleets of thousands: every group is indexed once, and the objective's coefficients come
from one array computation (risk.risk_table).
"""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass, field

from ortools.math_opt.python import mathopt

from .fleet import FIRST_YEAR, KINDS, REGIONS, Transformer
from .request import BASE, Request
from .risk import risk_table


@dataclass
class Built:
    model: mathopt.Model
    x: dict[tuple[str, int], mathopt.Variable]      # x[i, t] = 1: replace transformer i in year t
    budget: dict[int, mathopt.LinearConstraint]     # one row per year
    out: dict[tuple[str, int], mathopt.Variable] = field(default_factory=dict)   # out[s, t] = 1: outage


def relax(built: Built) -> Built:
    """The LP relaxation, in place: every variable continuous within its bounds."""
    for v in built.model.variables():
        v.integer = False
    return built


def candidates(fleet: list[Transformer], request: Request) -> list[Transformer]:
    return [t for t in fleet if t.age >= request.min_age]


def group(units: list[Transformer], key: Callable[[Transformer], str]) -> dict[str, list[Transformer]]:
    """Units by a key, in one pass, with the keys sorted."""
    found: dict[str, list[Transformer]] = {}
    for t in units:
        found.setdefault(key(t), []).append(t)
    return dict(sorted(found.items()))


def build(fleet: list[Transformer], request: Request) -> Built:
    model = mathopt.Model(name="renewal")
    units, years = candidates(fleet, request), request.plan_years()
    x = {(t.tid, y): model.add_binary_variable(name=f"x_{t.tid}_{y}") for t in units for y in years}
    for t in units:
        model.add_linear_constraint(mathopt.fast_sum(x[t.tid, y] for y in years) <= 1, name=f"once_{t.tid}")
    by_substation = group(units, lambda t: t.substation)
    by_region = group(units, lambda t: t.region)
    out = {}
    if request.has_outages():
        out = {(s, y): model.add_binary_variable(name=f"out_{s}_{y}") for s in by_substation for y in years}
        for s, members in by_substation.items():
            for y in years:
                if request.link == "aggregated":
                    # One row per substation and year: n_s * out[s, t] covers all its replacements.
                    model.add_linear_constraint(mathopt.fast_sum(x[t.tid, y] for t in members)
                                                <= len(members) * out[s, y], name=f"outage_{s}_{y}")
                else:
                    # One row per unit and year: the stronger form (lesson 6.7.1). Each aggregated
                    # row is the sum of these, so their LP relaxation allows less.
                    for t in members:
                        model.add_linear_constraint(x[t.tid, y] <= out[s, y], name=f"outage_{t.tid}_{y}")
        if request.outages is not None:
            for r in REGIONS:
                in_region = sorted({t.substation for t in by_region.get(r, [])})
                for y in years:
                    if in_region:
                        model.add_linear_constraint(mathopt.fast_sum(out[s, y] for s in in_region)
                                                    <= request.outages, name=f"coord_{r}_{y}")
    if request.crew_weeks is not None:
        for r in REGIONS:
            for y in years:
                if r in by_region:
                    model.add_linear_constraint(
                        mathopt.fast_sum(KINDS[t.kind].crew_weeks * x[t.tid, y] for t in by_region[r])
                        <= request.crew_weeks, name=f"crews_{r}_{y}")
    if request.lead_times:
        by_kind = group(units, lambda t: t.kind)
        for kind, k in KINDS.items():
            # Before FIRST_YEAR + lead, no unit ordered now has arrived: each such replacement uses a spare.
            early = [x[t.tid, y] for t in by_kind.get(kind, []) for y in years if y < FIRST_YEAR + k.lead_years]
            if early:
                model.add_linear_constraint(mathopt.fast_sum(early) <= request.spares.get(kind, 0),
                                            name=f"spares_{kind}")
    budget = {}
    for y in years:
        spend = mathopt.fast_sum(t.cost * x[t.tid, y] for t in units)
        if out:
            spend += request.outage_cost * mathopt.fast_sum(out[s, y] for s in by_substation)
        budget[y] = model.add_linear_constraint(spend <= request.budget, name=f"budget_{y}")
    scenarios = request.scenarios or (BASE,)
    tables = [risk_table(units, request, s) for s in scenarios]

    def removed(rr) -> mathopt.LinearSum:
        return mathopt.fast_sum(rr[i, j] * x[t.tid, y] for i, t in enumerate(units) for j, y in enumerate(years))

    if request.objective == "worst":
        # Max-min: `worst` can be no more than what the plan removes under any scenario. Its upper
        # bound is what every unit at its best year would remove in the least generous scenario.
        most = min(float(rr.clip(min=0.0).max(axis=1, initial=0.0).sum()) for rr in tables)
        worst = model.add_variable(lb=0.0, ub=most, name="worst")
        for s, rr in zip(scenarios, tables):
            model.add_linear_constraint(worst <= removed(rr), name=f"worst_{s.name}")
        model.maximize(worst)
    else:
        total = sum(s.weight for s in scenarios)
        model.maximize(removed(sum(s.weight / total * rr for s, rr in zip(scenarios, tables))))
    return Built(model, x, budget, out)

"""The planner's entry point: a request in, a plan out."""

from __future__ import annotations

from ortools.math_opt.python import mathopt

from .fleet import Transformer
from .model import build, relax
from .request import Plan, Request
from .solve import is_feasible, read_plan, solve_quietly


def plan(fleet: list[Transformer], request: Request) -> Plan:
    """The replacements that remove the most risk within the request's rules."""
    built = build(fleet, request)
    params = mathopt.SolveParameters(relative_gap_tolerance=request.gap)
    return read_plan(built, solve_quietly(built.model, params))


def feasible(fleet: list[Transformer], request: Request, replace: dict[str, int]) -> bool:
    """Does the model allow exactly these replacements (id -> year)? Every other choice is held at 0."""
    built = build(fleet, request)
    for (tid, y), var in built.x.items():
        var.lower_bound = var.upper_bound = 1 if replace.get(tid) == y else 0
    return is_feasible(solve_quietly(built.model))


def lp_bound(fleet: list[Transformer], request: Request) -> float:
    """The LP relaxation's optimum: an upper bound on every plan's risk removed (lesson 6.7.1)."""
    built = relax(build(fleet, request))
    return solve_quietly(built.model).objective_value()

"""The reference builder: the model before it was built for scale, one plain loop per row family.

It is slow at scale and kept on purpose: the fast builder in model.py is correct only if it makes
exactly this model (lesson 11.1.2).
"""

from __future__ import annotations

from ortools.math_opt.python import mathopt

from .fleet import FIRST_YEAR, KINDS, REGIONS, Transformer
from .model import Built, candidates
from .request import Request
from .risk import risk_removed


def build_reference(fleet: list[Transformer], request: Request) -> Built:
    model = mathopt.Model(name="renewal")
    units, years = candidates(fleet, request), request.plan_years()
    x = {(t.tid, y): model.add_binary_variable(name=f"x_{t.tid}_{y}") for t in units for y in years}
    for t in units:
        model.add_linear_constraint(sum(x[t.tid, y] for y in years) <= 1, name=f"once_{t.tid}")
    out = {}
    if request.has_outages():
        substations = sorted({t.substation for t in units})
        out = {(s, y): model.add_binary_variable(name=f"out_{s}_{y}") for s in substations for y in years}
        for s in substations:
            for y in years:
                members = [t for t in units if t.substation == s]
                # One row per substation and year: any replacement there needs the outage.
                model.add_linear_constraint(sum(x[t.tid, y] for t in members) <= len(members) * out[s, y],
                                            name=f"outage_{s}_{y}")
        if request.outages is not None:
            for r in REGIONS:
                in_region = sorted({t.substation for t in units if t.region == r})
                for y in years:
                    if in_region:
                        model.add_linear_constraint(sum(out[s, y] for s in in_region) <= request.outages,
                                                    name=f"coord_{r}_{y}")
    if request.crew_weeks is not None:
        for r in REGIONS:
            for y in years:
                in_region = [t for t in units if t.region == r]
                if in_region:
                    model.add_linear_constraint(
                        sum(KINDS[t.kind].crew_weeks * x[t.tid, y] for t in in_region) <= request.crew_weeks,
                        name=f"crews_{r}_{y}")
    if request.lead_times:
        for kind, k in KINDS.items():
            # Before FIRST_YEAR + lead, no unit ordered now has arrived: each such replacement uses a spare.
            early = [x[t.tid, y] for t in units if t.kind == kind for y in years if y < FIRST_YEAR + k.lead_years]
            if early:
                model.add_linear_constraint(sum(early) <= request.spares.get(kind, 0), name=f"spares_{kind}")
    budget = {}
    for y in years:
        spend = sum(t.cost * x[t.tid, y] for t in units)
        spend += request.outage_cost * sum(v for (s, year), v in out.items() if year == y)
        budget[y] = model.add_linear_constraint(spend <= request.budget, name=f"budget_{y}")
    model.maximize(sum(risk_removed(t, y, request) * x[t.tid, y] for t in units for y in years))
    return Built(model, x, budget, out)

"""What a list of replacements costs and what it removes."""

from __future__ import annotations

from dataclasses import dataclass

from .fleet import Transformer, risk


@dataclass(frozen=True)
class Summary:
    units: int
    spend: int              # $k
    risk_removed: float     # $k of expected failure cost this year


def summarize(fleet: list[Transformer], chosen: list[str]) -> Summary:
    by_id = {t.tid: t for t in fleet}
    units = [by_id[tid] for tid in chosen]
    return Summary(len(units), sum(t.cost for t in units), sum(risk(t) for t in units))


def outages(fleet: list[Transformer], replace: dict[str, int]) -> set[tuple[str, int]]:
    """The (substation, year) outages the replacements need: one per substation and year."""
    substation = {t.tid: t.substation for t in fleet}
    return {(substation[tid], y) for tid, y in replace.items()}


def spend_by_year(fleet: list[Transformer], replace: dict[str, int], outage_cost: int = 0) -> dict[int, int]:
    """What the replacements cost in each year, with their outages, $k."""
    cost = {t.tid: t.cost for t in fleet}
    spend: dict[int, int] = {}
    for tid, y in replace.items():
        spend[y] = spend.get(y, 0) + cost[tid]
    for _, y in outages(fleet, replace):
        spend[y] += outage_cost
    return dict(sorted(spend.items()))

"""A rolling horizon (lesson 11.3.5): plan a few years at a time and keep only the first of them."""

from __future__ import annotations

from ortools.math_opt.python import mathopt

from .fleet import Transformer
from .model import build
from .request import Plan, Request
from .solve import is_feasible, read_plan, solve_quietly


def rolling(fleet: list[Transformer], request: Request, window: int = 3, keep: int = 1) -> Plan:
    """Solve years [a, a + window) with earlier years fixed and later ones held at zero; keep `keep` years.

    Budget, crew and spare rows stay in the model for every year, so what a window decides is
    counted against all of them. The plan's value is exact; its bound is only the last window's.
    """
    built = build(fleet, request)
    years = list(request.plan_years())
    variables = {**built.x, **built.out}            # keyed (unit or substation, year)
    decided: dict[tuple[str, int], int] = {}
    params = mathopt.SolveParameters(relative_gap_tolerance=request.gap)
    result = None
    for i in range(0, len(years), keep):
        last = years[min(i + window, len(years)) - 1]
        for key, var in variables.items():
            if key in decided:
                var.lower_bound = var.upper_bound = decided[key]
            elif key[1] > last:
                var.lower_bound = var.upper_bound = 0
            else:
                var.lower_bound, var.upper_bound = 0, 1
        result = solve_quietly(built.model, params)
        if not is_feasible(result):
            return read_plan(built, result)
        kept = years[i:i + keep] if last != years[-1] else years[i:]
        for key, var in variables.items():
            if key[1] in kept:
                decided[key] = round(result.variable_values(var))
        if last == years[-1]:
            break
    return read_plan(built, result)

"""Solve with HiGHS and read the plan back."""

from __future__ import annotations

import ctypes
import os
import sys

from ortools.math_opt.python import mathopt

from .request import Plan

FOUND = (mathopt.TerminationReason.OPTIMAL, mathopt.TerminationReason.FEASIBLE)
FOUND_NAMES = {reason.name for reason in FOUND}


def solve_quietly(model: mathopt.Model, params: mathopt.SolveParameters | None = None) -> mathopt.SolveResult:
    """Solve with HiGHS, with the process's standard output pointed at /dev/null for the solve.

    The HiGHS bundled in OR-Tools 9.15 can print a stray debug line on a MIP solve with no log asked
    for; it is buffered C output, so it is flushed before the output is restored.
    """
    sys.stdout.flush()
    saved, sink = os.dup(1), os.open(os.devnull, os.O_WRONLY)
    os.dup2(sink, 1)
    try:
        return mathopt.solve(model, mathopt.SolverType.HIGHS, params=params)
    finally:
        ctypes.CDLL(None).fflush(None)
        os.dup2(saved, 1)
        os.close(saved)
        os.close(sink)


def is_feasible(result: mathopt.SolveResult) -> bool:
    return result.termination.reason in FOUND


def read_plan(built, result: mathopt.SolveResult) -> Plan:
    if not is_feasible(result):
        return Plan({}, 0.0, 0.0, result.termination.reason.name)
    replace = {tid: y for (tid, y), var in built.x.items() if result.variable_values(var) > 0.5}
    return Plan(replace, result.objective_value(), result.termination.objective_bounds.dual_bound,
                result.termination.reason.name)

